/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.html5;import page2020.view.Tag;public class H5time extends Tag<H5time> {	public static final class Attr {		public static final String datetime = "datetime";	}	public H5time() {		super("time");	}	public H5time datetime(String datetime) {		super.getAttrMap().put("datetime", datetime);		return this;	}	@Override	protected boolean isAttr(String attrName) {		switch (this.attrName(attrName)) {		case Attr.datetime:			return true;		default:			return super.isAttr(attrName);		}	}	}